(() => {
const card=document.querySelector('.lobbycard');const box=document.createElement('section');box.className='preflight';box.innerHTML='<strong>Preparação do navegador</strong><p id="compatibilityStatus"></p><button id="prepareBeforeJoin" type="button">Preparar tradução antes de entrar</button><p id="preflightStatus" role="status"></p>';card.append(box);
const voice=!!(window.SpeechRecognition||window.webkitSpeechRecognition),translation=!!window.Translator,media=!!navigator.mediaDevices?.getUserMedia;
document.getElementById('compatibilityStatus').textContent=[media?'Câmera e microfone disponíveis.':'Captura de mídia indisponível.',voice?'Reconhecimento de voz do navegador disponível.':navigator.gpu?'Whisper no dispositivo disponível após preparação.':'Reconhecimento indisponível; use texto digitado.',translation?'Tradutor integrado disponível; os idiomas precisam ser preparados.':'Tradução integrada indisponível neste navegador; você verá o texto original.'].join(' ');
document.getElementById('prepareBeforeJoin').onclick=async()=>{const status=document.getElementById('preflightStatus'),button=document.getElementById('prepareBeforeJoin');button.disabled=true;try{if(!translation)throw Error('Use Chrome de desktop atualizado para tradução integrada.');const rid=new URLSearchParams(location.search).get('room');const target=rid?document.getElementById('studentLanguage').value:'en';let source=document.getElementById('teacherLanguage').value;if(rid){const response=await fetch('/api/rooms/'+rid+'/info');if(!response.ok)throw Error('Não foi possível verificar os idiomas da sala.');const info=await response.json();source=info.teacherLanguage||'pt'}status.textContent='Preparando o pacote de idioma…';await getTranslator(source,target,true);status.textContent='Pronto: '+names[source]+' → '+names[target]+'. Você pode entrar na sala.';}catch(error){status.textContent=error.message}finally{button.disabled=false}};
})();
